package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import java.math.*;import java.time.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
/** Original-owner stop intent. A post-dispatch request is not provider termination or a billing receipt. */
public final class FormalInvocationCancellation {
 private final JdbcTemplate db;private final FormalVerificationJobs jobs;private final FormalInvocationReservations reservations;private final ResourceReadAuthority resources;private final FormalInvocationSchema schema;
 public FormalInvocationCancellation(DataSource data,FormalVerificationJobs jobs,FormalInvocationReservations reservations,ResourceReadAuthority resources,FormalInvocationSchema schema){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.jobs=jobs;this.reservations=reservations;this.resources=resources;this.schema=schema;}
 JsonNode cancel(EnterpriseAccess.Admission a,String invocation,String key,String reason)throws Exception{
  WireValues.uuid(invocation);if(key==null||!key.matches("[!-~]{16,128}")||reason==null||reason.isBlank()||reason.length()>2000||!reason.equals(reason.strip()))throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);
  String tenant=a.context().tenant_id(),actor=a.actorId();var run=one(db.query("SELECT run_id,created_by,config_id FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,invocation));if(!actor.equals(run.get(1)))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);var job=jobs.byRun(tenant,run.get(0));reservations.requireRegistered(job,invocation);resources.require(a,new PermissionProtocol.Scope(tenant,job.project(),"CONFIGURATION",run.get(2)),"model.verify","MODEL_VERIFICATION");
  String request=schema.canonical(Map.of("schema_version","1.0.0","invocation_id",invocation,"reason",reason));String requestHash=WireValues.sha256(request.getBytes(java.nio.charset.StandardCharsets.UTF_8));var old=db.query("SELECT request_sha256,receipt_json,receipt_sha256 FROM formal_invocation_cancellation WHERE tenant_id=? AND created_by=? AND idempotency_key=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,actor,key);if(old.size()>1)bad();if(!old.isEmpty()){if(!old.get(0).get(0).equals(requestHash))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);return verify(job,key,request,old.get(0).get(1),old.get(0).get(2));}
  requireAbsentAudit(tenant,actor,key);
  var state=one(db.query("SELECT status,dispatch_generation,revision FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2 FOR UPDATE",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,invocation));var attempts=db.query("SELECT attempt_id FROM formal_invocation_attempt WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->r.getString(1),tenant,invocation);if(attempts.size()>1)bad();boolean before="RESERVED".equals(state.get(0));if(before&&(!"0".equals(state.get(1))||!attempts.isEmpty())||!before&&("0".equals(state.get(1))||attempts.size()!=1))bad();
  if(Set.of("SUCCEEDED","FAILED","CANCELLED").contains(state.get(0)))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
  var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));
  if(before){var rows=db.query("SELECT reservation_id,budget_id,upper_amount,upper_tokens,revision,status FROM budget_reservation WHERE tenant_id=? AND invocation_id=? ORDER BY budget_id LIMIT 3 FOR UPDATE",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)),tenant,invocation);if(rows.size()!=2)bad();for(var r:rows){if(!"RESERVED".equals(r.get(5)))bad();var account=one(db.query("SELECT revision,reserved,reserved_tokens,reserved_calls FROM budget_account WHERE tenant_id=? AND budget_id=? LIMIT 2 FOR UPDATE",(rs,n)->List.of(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4)),tenant,r.get(1)));if(new BigDecimal(account.get(1)).compareTo(new BigDecimal(r.get(2)))<0||new BigInteger(account.get(2)).compareTo(new BigInteger(r.get(3)))<0||new BigInteger(account.get(3)).signum()<=0)bad();changed(db.update("UPDATE budget_account SET reserved=reserved-?,reserved_tokens=reserved_tokens-?,reserved_calls=reserved_calls-1,revision=revision+1,updated_at=? WHERE tenant_id=? AND budget_id=? AND revision=?",r.get(2),r.get(3),now,tenant,r.get(1),account.get(0)));changed(db.update("UPDATE budget_reservation SET status='RELEASED',revision=revision+1,updated_at=? WHERE tenant_id=? AND reservation_id=? AND revision=? AND status='RESERVED'",now,tenant,r.get(0),r.get(4)));}}
  // If an immutable UNKNOWN observation exists, preserve its actual execution/accounting snapshot.
  boolean hasObservation=!db.query("SELECT invocation_id FROM formal_invocation_accounting WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->r.getString(1),tenant,invocation).isEmpty();String next=before?"CANCELLED":hasObservation?state.get(0):"CANCEL_REQUESTED";
  changed(db.update("UPDATE invocation SET status=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND invocation_id=? AND revision=?",next,now,tenant,invocation,state.get(2)));
  if(before){changed(db.update("UPDATE run_step SET status='CANCELLED',revision=revision+1,updated_at=? WHERE tenant_id=? AND run_id=? AND step_id=? AND status IN ('READY','RUNNING')",now,tenant,job.run(),job.step()));changed(db.update("UPDATE system_job_run SET status='CANCELLED',ended_at=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND run_id=? AND status='RUNNING'",now,now,tenant,job.run()));}
  var receipt=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("schema_version","1.0.0").put("invocation_id",invocation).put("verification_id",job.verification()).put("request_body_sha256",requestHash).put("original_key_sha256",keyHash(key)).put("status",next).put("before_dispatch",before).put("reservations_released",before).put("provider_termination_confirmed",false).put("created_at",now.toInstant(ZoneOffset.UTC).toString());String raw=schema.canonical(receipt),hash=schema.hash(receipt);var row=meta(job,now);row.put("invocation_id",invocation);row.put("idempotency_key",key);row.put("canonical_request",request);row.put("request_sha256",requestHash);row.put("receipt_json",raw);row.put("receipt_sha256",hash);insert("formal_invocation_cancellation",row);var audit=meta(job,now);audit.put("audit_id",UUID.randomUUID().toString());audit.put("subject_id",actor);audit.put("action","model.invocation_cancel_requested");audit.put("resource_ref",raw);audit.put("result","SUCCESS");audit.put("request_id",requestHash);audit.put("trace_id",invocation);insert("audit_event",audit);insert("outbox_event",Map.of("tenant_id",tenant,"event_id",UUID.randomUUID().toString(),"aggregate_id",invocation,"aggregate_revision",new BigInteger(state.get(2)).add(BigInteger.ONE),"event_type","model.invocation_cancel_requested","payload",raw,"occurred_at",now));return verify(job,key,request,raw,hash);
 }
 Optional<JsonNode> recover(EnterpriseAccess.Admission a,String key)throws Exception{
  if(key==null||!key.matches("[!-~]{16,128}"))throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);String tenant=a.context().tenant_id(),actor=a.actorId();
  var rows=db.query("SELECT canonical_request,receipt_json,receipt_sha256 FROM formal_invocation_cancellation WHERE tenant_id=? AND created_by=? AND idempotency_key=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,actor,key);if(rows.size()>1)bad();if(rows.isEmpty()){requireAbsentAudit(tenant,actor,key);return Optional.empty();}
  var request=schema.parse(rows.get(0).get(0));String invocation=request.required("invocation_id").textValue();var run=one(db.query("SELECT run_id,created_by,config_id FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,invocation));if(!actor.equals(run.get(1)))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);var job=jobs.byRun(tenant,run.get(0));reservations.requireRegistered(job,invocation);resources.require(a,new PermissionProtocol.Scope(tenant,job.project(),"CONFIGURATION",run.get(2)),"model.verify","MODEL_VERIFICATION");return Optional.of(verify(job,key,rows.get(0).get(0),rows.get(0).get(1),rows.get(0).get(2)));
 }
 private void requireAbsentAudit(String tenant,String actor,String key)throws Exception{var evidence=db.query("SELECT audit_id FROM audit_event WHERE tenant_id=? AND subject_id=? AND action='model.invocation_cancel_requested' AND JSON_UNQUOTE(JSON_EXTRACT(resource_ref,'$.original_key_sha256'))=? LIMIT 2",(r,n)->r.getString(1),tenant,actor,keyHash(key));if(!evidence.isEmpty())bad();}
 private static String keyHash(String key)throws Exception{return WireValues.sha256(key.getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
 private JsonNode verify(FormalVerificationJobs.Job job,String key,String request,String raw,String hash)throws Exception{var r=schema.parse(raw);if(!keyHash(key).equals(r.required("original_key_sha256").textValue())||!raw.equals(schema.canonical(r))||!hash.equals(schema.hash(r))||!WireValues.sha256(request.getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(r.required("request_body_sha256").textValue()))bad();var now=LocalDateTime.ofInstant(Instant.parse(r.required("created_at").textValue()),ZoneOffset.UTC);if(one(db.query("SELECT COUNT(*) FROM formal_invocation_cancellation WHERE tenant_id=? AND project_id=? AND invocation_id=? AND idempotency_key=? AND canonical_request=? AND request_sha256=? AND receipt_json=? AND receipt_sha256=? AND created_by=? AND created_at=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=?",(rs,n)->rs.getInt(1),job.tenant(),job.project(),r.required("invocation_id").textValue(),key,request,r.required("request_body_sha256").textValue(),raw,hash,job.actor(),now,schema.manifestSha256(),job.classification()))!=1)bad();var audit=one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND subject_id=? AND action='model.invocation_cancel_requested' AND request_id=? AND trace_id=? AND created_at=? LIMIT 2",(rs,n)->rs.getString(1),job.tenant(),job.actor(),r.required("request_body_sha256").textValue(),r.required("invocation_id").textValue(),now));var event=one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND event_type='model.invocation_cancel_requested' AND occurred_at=? LIMIT 2",(rs,n)->rs.getString(1),job.tenant(),r.required("invocation_id").textValue(),now));if(!raw.equals(schema.canonical(schema.parse(audit)))||!raw.equals(schema.canonical(schema.parse(event))))bad();return r;}
 private Map<String,Object> meta(FormalVerificationJobs.Job j,LocalDateTime now){var m=new LinkedHashMap<String,Object>();m.put("tenant_id",j.tenant());m.put("project_id",j.project());m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",schema.manifestSha256());m.put("created_by",j.actor());m.put("created_at",now);m.put("classification",j.classification());return m;}private void insert(String table,Map<String,Object> v){var keys=new ArrayList<>(v.keySet());changed(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(v::get).toArray()));}private static void changed(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
